fn len(s: &String) -> usize {
    s.len()
}

fn main() {
    let s = String::from("hi");
    println!("{}", len(&s));
    println!("{}", s);
}

fn main() {
    let mut count = 0;
    count += 1;
    println!("{}", count);
}

enum Status { Ok, Error }

fn main() {
    let s = Status::Ok;
    match s {
        Status::Ok => println!("ok"),
        Status::Error => println!("error"),
    }
}

enum Direction {
    North,
    South,
    East,
    West,
}

fn first_char(s: &str) -> Option<char> {
    s.chars().next()
}

fn main() {
    if let Some(c) = first_char("hi") {
        println!("{}", c);
    }
}

fn parse_num(s: &str) -> Result<i32, std::num::ParseIntError> {
    s.parse()
}

fn main() {
    println!("{:?}", parse_num("12"));
}

fn sum(nums: &[i32]) -> i32 {
    nums.iter().sum()
}

fn main() {
    let v = vec![1, 2, 3];
    println!("{}", sum(&v[1..]));
}

