trait Clock { fn now(&self) -> u64; }
struct FixedClock(u64);
impl Clock for FixedClock { fn now(&self) -> u64 { self.0 } }
fn expired<C: Clock>(c: &C, deadline: u64) -> bool { c.now() > deadline }

