use std::pin::Pin;

fn poll_once<F: std::future::Future>(f: Pin<&mut F>) {
    let _ = f;
}

fn with_str<F>(s: String, f: F)
where
    F: for<'a> FnOnce(&'a str),
{
    f(&s)
}

use std::mem::MaybeUninit;

let mut x = MaybeUninit::<u32>::uninit();
x.write(42);
let x = unsafe { x.assume_init() };
assert_eq!(x, 42);

